test('Hoist rises through an open shaft, exits onto the loft and recovers interrupted rides',()=>{const s=run(street.slice(0,4));travel(s,6,-8);action(s,'interact');travel(s,6.8,.5);action(s,'interact');for(let i=0;i<60;i++)tick(s,{},1/60);const m=store();assert.ok(save(s,m).ok);assert.equal(load(m).state.lift,null);for(let i=0;i<80;i++)tick(s,{},1/60);assert.equal(s.hoistY,4.4);travel(s,10,.5);assert.ok(s.y>4.3);assert.equal(floors.some(f=>f.y>2&&Math.abs(f.x-6.8)<f.w/2&&Math.abs(f.z-.5)<f.d/2),false);});

